result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/rfm_winsor.py", "content": """"RFM monetary scoring with and without winsorization of outliers.

Naive quintile scoring on customer totals lets a handful of whales squash
everyone else into bucket 1. Capping totals at the 95th percentile before
scoring keeps the buckets meaningful.
"""

import numpy as np


def _quintile_scores(values):
    """Score values 1..5 using the 20/40/60/80th percentile cut points."""
    values = np.asarray(values, dtype=float)
    edges = np.percentile(values, [20, 40, 60, 80])
    return np.digitize(values, edges, right=False) + 1


def mscore_raw(amounts):
    """Plain monetary score: quintiles on raw customer totals."""
    return _quintile_scores(amounts)


def mscore_winsorized(amounts):
    """Cap totals at the 95th percentile, then take quintiles."""
    amounts = np.asarray(amounts, dtype=float)
    capped = np.minimum(amounts, np.percentile(amounts, 95))
    return _quintile_scores(capped)


# ---------------------------------------------------------------- tests
import pytest


def _customer_totals():
    """500 totals: 490 lognormal customers + 10 whales at 100x median."""
    rng = np.random.default_rng(55)
    base = rng.lognormal(mean=3.0, sigma=0.4, size=490)
    return np.concatenate([base, np.full(10, 100.0 * np.median(base))])


def _whale_scores(scores):
    return scores[-10:]


def test_raw_and_winsorized_return_valid_scores():
    totals = _customer_totals()
    for scorer in (mscore_raw, mscore_winsorized):
        scores = scorer(totals)
        assert len(scores) == len(totals)
        assert set(np.unique(scores)) <= {1, 2, 3, 4, 5}
        assert set(np.unique(scores)) >= {1, 5}  # both extremes populated


def test_whales_score_5_under_both_schemes():
    totals = _customer_totals()
    assert (_whale_scores(mscore_raw(totals)) == 5).sum() >= 8
    assert (_whale_scores(mscore_winsorized(totals)) == 5).sum() >= 8


def _bucket_ratio(scores, totals, bucket=5):
    members = totals[scores == bucket]
    return members.max() / members.min()


def test_raw_top_bucket_is_distorted_by_whales():
    totals = _customer_totals()
    assert _bucket_ratio(mscore_raw(totals), totals) > 20


def test_winsorized_top_bucket_is_compressed():
    totals = _customer_totals()
    assert _bucket_ratio(mscore_winsorized(totals), totals) < 20
